+        CreateWorkspaceRequest {
+            name: self.name.clone(),
+            ..Default::default()
+        }
+        .authorize(state, principal)
+        .await
+    }
+    async fn execute(
+        _state: &Arc<ServerState>,
+        request: Request<Self>,
+    ) -> Result<Response<Self::Output>, Status> {
